function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 20) return 'words needs 1 to 20 strings.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 100) return 'Each word has 1 to 100 letters.';
    if (!/^[A-Za-z]+$/.test(word)) return 'Words contain only English letters.';
  }
  return null;
}

