function generate(rand, size) {
  const rows = ["qwertyuiop", "asdfghjkl", "zxcvbnm"];
  const all = rows.join('');
  const pick = s => s[Math.floor(rand() * s.length)];
  const letter = s => { const c = pick(s); return rand() < 0.3 ? c.toUpperCase() : c; };
  const count = size === 'large' ? 20 : 1 + Math.floor(rand() * 6);
  const words = [];
  for (let i = 0; i < count; i++) {
    const length = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
    const mode = rand();
    let word = '';
    if (mode < 0.5) {
      const row = pick(rows);
      for (let j = 0; j < length; j++) word += letter(row);
    } else if (mode < 0.75) {
      // One row except for a single stray letter, which is the hardest case to get right.
      const row = pick(rows);
      for (let j = 0; j < length; j++) word += letter(row);
      const at = Math.floor(rand() * length);
      word = word.slice(0, at) + letter(all) + word.slice(at + 1);
    } else {
      for (let j = 0; j < length; j++) word += letter(all);
    }
    words.push(word);
  }
  return [words];
}
